<?php
/** NexaBiz incremental storefront design patch. CLI only. No composer dependency. */
if(PHP_SAPI!=='cli'){http_response_code(403);exit('CLI only');}
$command=$argv[1]??'--help';
if(!in_array($command,['--dry-run','--apply','--rollback','--help'],true)){fwrite(STDERR,"Invalid command.\n");exit(2);}
$root=__DIR__;
if(!is_file($root.'/artisan')||!is_file($root.'/composer.json')){fwrite(STDERR,"Put this file in the Laravel root beside artisan and composer.json.\n");exit(2);}
$backupRoot=$root.'/storage/app/nexabiz-patch-backups/2026-11-24-china-storefront';
$stateFile=$backupRoot.'/state.json';
function say($s){echo $s,"\n";}
function stop($s,$code=1){fwrite(STDERR,$s."\n");exit($code);}
function digest($f){return is_file($f)?hash_file('sha256',$f):null;}
function saveFile($path,$data){
 $dir=dirname($path);if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir))throw new RuntimeException('Cannot create '.$dir);
 $temp=$path.'.nexabiztemp';if(file_put_contents($temp,$data,LOCK_EX)===false)throw new RuntimeException('Cannot write '.$temp);
 if(!rename($temp,$path)){@unlink($temp);throw new RuntimeException('Cannot replace '.$path);}
}
if($command==='--help'){say('Usage: php '.basename(__FILE__).' --dry-run | --apply | --rollback');exit(0);}
if($command==='--rollback'){
 if(!is_file($stateFile))stop('No backup state found.');
 $state=json_decode(file_get_contents($stateFile),true,512,JSON_THROW_ON_ERROR);$conflicts=[];
 foreach($state['entries'] as $name=>$record)if(digest($root.'/'.$name)!==($record['installed']??null))$conflicts[]=$name;
 if($conflicts)stop("Cannot roll back edited files:\n - ".implode("\n - ",$conflicts));
 foreach($state['entries'] as $name=>$record){
  $path=$root.'/'.$name;
  if($record['previous']===null){if(is_file($path))unlink($path);}
  else saveFile($path,file_get_contents($backupRoot.'/files/'.$name));
  say('RESTORED '.$name);
 }
 @unlink($stateFile);say('Rollback complete (files only, migrations unchanged).');exit(0);
}
if(is_file($stateFile))stop('Already applied. To restore files, use --rollback.');
$encoded=trim(substr(file_get_contents(__FILE__),__COMPILER_HALT_OFFSET__));
$decoded=base64_decode($encoded,true);if($decoded===false)stop('Corrupted payload.');
$plain=gzuncompress($decoded);if($plain===false)stop('Cannot decompress payload.');
$payload=json_decode($plain,true,512,JSON_THROW_ON_ERROR);$changes=[];$already=[];$conflicts=[];
foreach($payload['entries'] as $name=>$entry){
 if(!preg_match('~^(app/|routes/|database/|resources/|public/|NEXABIZ_CHINAONLINEBD_UI_NOTES\.md$)~',$name)||str_contains($name,'..')||str_contains($name,'\\'))stop('Unsafe patch path '.$name);
 $current=digest($root.'/'.$name);
 if($current===$entry['new']){$already[]=$name;continue;}
 if($current!==$entry['old']){$conflicts[]=$name;continue;}
 $changes[$name]=$entry;
}
say('NexaBiz storefront patch: '.count($changes).' changes; '.count($already).' already current; '.count($conflicts).' conflicts');
if($conflicts){foreach($conflicts as $name)say('CONFLICT '.$name);stop('Previous ecommerce patch version is required, or local files were modified. No files changed.');}
if($command==='--dry-run'){foreach($changes as $name=>$entry)say(($entry['old']===null?'ADD ':'UPDATE ').$name);exit(0);}
if(!$changes){say('Already current.');exit(0);}
$restore=[];
foreach($changes as $name=>$entry){
 $restore[$name]=['previous'=>$entry['old'],'installed'=>$entry['new']];
 if($entry['old']!==null){$backup=$backupRoot.'/files/'.$name;$dir=dirname($backup);
  if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir))stop('Cannot make backup directory.');
  if(!copy($root.'/'.$name,$backup))stop('Cannot back up '.$name);
 }
}
try{
 foreach($changes as $name=>$entry){
  $data=base64_decode($entry['data'],true);
  if($data===false||hash('sha256',$data)!==$entry['new'])throw new RuntimeException('Payload checksum mismatch for '.$name);
  saveFile($root.'/'.$name,$data);say('OK '.$name);
 }
 saveFile($stateFile,json_encode(['version'=>$payload['version'],'entries'=>$restore],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));
 say('Applied. Original files backed up in storage/app/nexabiz-patch-backups/');
}catch(Throwable $e){
 fwrite(STDERR,'Failed: '.$e->getMessage()."\nRestoring backups...\n");
 foreach($restore as $name=>$rec){$path=$root.'/'.$name;if($rec['previous']===null){if(is_file($path))@unlink($path);}else{$f=$backupRoot.'/files/'.$name;if(is_file($f))saveFile($path,file_get_contents($f));}}exit(1);
}
__halt_compiler();

